#!/usr/bin/env bash
# Validates a commit message: Conventional Commits format and English only.
# Used by the commit-msg hook (.githooks/commit-msg) and by CI.
#
# Usage: scripts/check-commit-msg.sh <file-with-message>
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
message="$(grep -v '^#' "$1" || true)"
subject="$(grep -m1 -v '^[[:space:]]*$' <<< "$message" || true)"

# Messages generated by git itself
if [[ "$subject" =~ ^(Merge|Revert\ \") ]]; then
    exit 0
fi

types='feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert'
# Case-insensitive so that "Feat: ..." or "Chore(cli): ..." are accepted too
shopt -s nocasematch
if ! [[ "$subject" =~ ^($types)(\([a-z0-9._-]+\))?!?:\ [^[:space:]].*$ ]]; then
    cat >&2 <<EOF
error: commit subject does not follow Conventional Commits:
  "$subject"

Expected: <type>(<optional scope>): <description>
Types:    ${types//|/, }
Example:  feat(crypto): add RSA-PSS signing service
EOF
    exit 1
fi

if (( ${#subject} > 72 )); then
    echo "error: commit subject is ${#subject} characters long (max 72)" >&2
    exit 1
fi

"$root/scripts/check-english.sh" "commit message" <<< "$message"
